import{_ as t,o as r,c as a,ah as o}from"./chunks/framework.C-FRNfAJ.js";const g=JSON.parse('{"title":"Lead Trainer","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/equipe/formateur.md","filePath":"src/en/guide/equipe/formateur.md"}'),n={name:"en/guide/equipe/formateur.md"};function s(i,e,d,h,c,l){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="lead-trainer" tabindex="-1">Lead Trainer <a class="header-anchor" href="#lead-trainer" aria-label="Permalink to &quot;Lead Trainer&quot;">​</a></h1><p>The Lead Trainer teaches and grades in <strong>Sève</strong>, and handles in <strong>Kura</strong> what concerns their cohorts: in-person attendance, retakes, remuneration tracking. The role is assigned by the Pedagogical Coordinator.</p><h2 id="your-cohorts" tabindex="-1">Your cohorts <a class="header-anchor" href="#your-cohorts" aria-label="Permalink to &quot;Your cohorts&quot;">​</a></h2><p><strong>Training → Cohorts</strong> lists only <strong>the cohorts you are assigned to</strong>. Opening another trainer&#39;s cohort is refused. Each page shows its dates, headcount, learners with their format and status, and the cohort&#39;s documents (see below).</p><p>In the learner list, a <strong>&quot;No image rights&quot;</strong> marker flags those who refused: do not share any recording in which they appear.</p><p>You cannot create, confirm, postpone or cancel a cohort: that is the Coordinator&#39;s business. Nor do you have access to the admission test&#39;s question bank.</p><h2 id="attendance" tabindex="-1">Attendance <a class="header-anchor" href="#attendance" aria-label="Permalink to &quot;Attendance&quot;">​</a></h2><p>From the cohort page, <strong>Attendance</strong> gives, for each learner, the absence rate (missed hours over the training&#39;s hours) with a marker at the 30% threshold, and the list of classes.</p><ul><li><strong>Virtual classes</strong> are read from Sève every hour. They appear here without you entering anything, and cannot be edited in Kura. For this, the Coordinator must have entered the cohort&#39;s Sève course id.</li><li><strong>In-person classes</strong> you enter yourself: <strong>Record a class</strong>, with the date and time, the length in minutes and an optional title.</li></ul><p>Entry is only possible <strong>once the cohort has started</strong>, and the class must have taken place. Each in-person or hybrid learner is <strong>present by default</strong>: untick those who are absent, or mark them late or absent. A late arrival counts as present, an excused absence as absent.</p><p>You can <strong>correct</strong> or <strong>delete</strong> an in-person class; rates are recalculated, and everything is logged. When a learner&#39;s rate exceeds 30%, they are notified, as is the pedagogical team, once only. A correction bringing it back under the threshold rearms the alert.</p><h2 id="grades-in-seve" tabindex="-1">Grades in Sève <a class="header-anchor" href="#grades-in-seve" aria-label="Permalink to &quot;Grades in Sève&quot;">​</a></h2><p>You grade each <strong>skill block</strong> in the Sève course gradebook, out of 20. For Kura to find the grade, the grade item carries the block&#39;s code as its <strong>ID number</strong>: <code>KURA-BLOC-{id}</code>. The codes of all blocks are listed on the cohort&#39;s <strong>Results</strong> page.</p><p>Grades flow back into Kura every hour. A new grade on an already graded block <strong>corrects</strong> the current attempt.</p><h2 id="results-and-retakes" tabindex="-1">Results and retakes <a class="header-anchor" href="#results-and-retakes" aria-label="Permalink to &quot;Results and retakes&quot;">​</a></h2><p>The cohort&#39;s <strong>Results</strong> page shows, for each learner, their grades by block, their average (weighted by block duration) and the jury&#39;s decision. A block is:</p><table tabindex="0"><thead><tr><th>Grade</th><th>Reading</th></tr></thead><tbody><tr><td>10/20 and more</td><td>Validated</td></tr><tr><td>From 8 to under 10</td><td>Compensable: made up by the average</td></tr><tr><td>Under 8</td><td>Eliminatory</td></tr></tbody></table><p>You can <strong>open a retake</strong> for a block under 10/20, <strong>at least 15 days</strong> after the block&#39;s last grade, within <strong>2 retakes</strong> (3 attempts in all). The page shows the date from which it is possible.</p><p>An open retake <strong>waits for the first grade given in Sève after it opens</strong> and fills itself. You can cancel it as long as it has not been graded.</p><p>The <strong>jury&#39;s</strong> decisions (tutored project, defence, internship) are entered by the Coordinator. Issuing the certificate is also up to them.</p><h2 id="the-cohort-s-documents" tabindex="-1">The cohort&#39;s documents <a class="header-anchor" href="#the-cohort-s-documents" aria-label="Permalink to &quot;The cohort&#39;s documents&quot;">​</a></h2><p>From the cohort page, you download, generated on demand:</p><ul><li>the <strong>provisional calendar</strong>: blocks, key dates, payment due dates, jury days, public holidays;</li><li>the <strong>defence report</strong>, once produced by the Coordinator.</li></ul><p>The activity report (seats, attendance, results) stays reserved for the Coordinator and the Administrator.</p><h2 id="your-remuneration" tabindex="-1">Your remuneration <a class="header-anchor" href="#your-remuneration" aria-label="Permalink to &quot;Your remuneration&quot;">​</a></h2><p><strong>Finance → My remuneration</strong> shows your lines <strong>cohort by cohort</strong> and the payouts received, with three totals: awaiting validation, validated to pay, paid.</p><p>Kura calculates your remuneration <strong>at the end of the cohort</strong>, at the rates in force at its start. The Coordinator adjusts it if needed and validates it; payment is made outside Kura and they record it. If there are several trainers on a cohort, your share is split equally.</p>',27)])])}const p=t(n,[["render",s]]);export{g as __pageData,p as default};
